package com.chubb.apac.claims.modulith.config.controller;
import com.chubb.apac.claims.modulith.common.enums.Market;import com.chubb.apac.claims.modulith.config.dto.MarketConfigurationResponse;import com.chubb.apac.claims.modulith.config.service.ConfigurationQueryService;import java.util.List;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ConfigurationControllerTest {ConfigurationQueryService service;MockMvc mvc;@BeforeEach void setup(){service=mock(ConfigurationQueryService.class);mvc=MockMvcBuilders.standaloneSetup(new ConfigurationController(service)).build();}@Test void listsMarkets()throws Exception{when(service.markets()).thenReturn(List.of(new MarketConfigurationResponse(Market.SG,"Singapore","SGD","en","Asia/Singapore")));mvc.perform(get("/api/v1/config/markets")).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].marketId").value("SG"));}}
